const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
// same rule as the SQL seed: the latest date on or before day n that falls on the slot's weekday (0 = Monday)
const onWeekday = (n, wd) => { const d = day(n); const cur = (d.getDay() + 6) % 7; d.setDate(d.getDate() - ((cur - wd + 7) % 7)); return iso(d); };
